-- SOLO para una base PostgreSQL VACÍA. En una base existente aplicar V1 y V2 tras respaldo.
BEGIN;
CREATE TABLE rol(id_rol INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(255) NOT NULL);
CREATE TABLE usuario(id_usuario INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,codigo VARCHAR(255) NOT NULL,contrasena VARCHAR(255) NOT NULL,estado BOOLEAN,rol_id INTEGER REFERENCES rol);
CREATE TABLE admin(id_admin INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,usuario_id INTEGER UNIQUE REFERENCES usuario);
CREATE TABLE cliente(id_cliente INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(255) NOT NULL,apellido VARCHAR(255) NOT NULL,telefono VARCHAR(255) NOT NULL,estado BOOLEAN,usuario_id INTEGER UNIQUE REFERENCES usuario);
CREATE TABLE giro(id_giro INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(255) NOT NULL);
CREATE TABLE moneda(id_moneda INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(255) NOT NULL,simbolo VARCHAR(255) NOT NULL);
CREATE TABLE unidad_medida(id_um INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(255) NOT NULL);
CREATE TABLE negocio(id_negocio INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,razon_social VARCHAR(255) NOT NULL,direccion VARCHAR(255) NOT NULL,telefono VARCHAR(255) NOT NULL,estado BOOLEAN,giro_id INTEGER REFERENCES giro,usuario_id INTEGER UNIQUE REFERENCES usuario);
CREATE TABLE cuenta_credito(id_cc INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,deuda DOUBLE PRECISION NOT NULL,limite DOUBLE PRECISION NOT NULL,max_meses INTEGER NOT NULL,dia_corte INTEGER NOT NULL,dia_pago INTEGER NOT NULL,estado BOOLEAN,moneda_id INTEGER REFERENCES moneda,negocio_id INTEGER REFERENCES negocio,cliente_id INTEGER REFERENCES cliente);
CREATE TABLE tasa(id_tasa INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,porcentaje DOUBLE PRECISION NOT NULL,periodicidad DOUBLE PRECISION NOT NULL,capitalizacion DOUBLE PRECISION NOT NULL,nominal_efectiva BOOLEAN NOT NULL,normal_moratoria BOOLEAN NOT NULL,cc_id INTEGER REFERENCES cuenta_credito);
CREATE TABLE producto(id_producto INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(255) NOT NULL,descripcion VARCHAR(255) NOT NULL,marca VARCHAR(255) NOT NULL,proovedor VARCHAR(255) NOT NULL,imagen_url VARCHAR(255) NOT NULL,precio_contado DOUBLE PRECISION NOT NULL,precio_lista DOUBLE PRECISION NOT NULL,pago_cuotas BOOLEAN,estado BOOLEAN,um_id INTEGER REFERENCES unidad_medida,negocio_id INTEGER REFERENCES negocio);
CREATE TABLE compra(id_compra INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,fecha DATE,tasa DOUBLE PRECISION,tasa_mora DOUBLE PRECISION,total_inicial DOUBLE PRECISION,total_gracia DOUBLE PRECISION,intereses DOUBLE PRECISION,moras DOUBLE PRECISION,total_final DOUBLE PRECISION,num_meses INTEGER,contado_credito BOOLEAN,final_cuotas BOOLEAN,cc_id INTEGER REFERENCES cuenta_credito);
CREATE TABLE item(id_item INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cantidad INTEGER NOT NULL,producto_id INTEGER REFERENCES producto,compra_id INTEGER REFERENCES compra);
CREATE TABLE cuota(id_cuota INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,fecha_vencimiento TIMESTAMP(6) NOT NULL,num INTEGER NOT NULL,intereses DOUBLE PRECISION NOT NULL,moras DOUBLE PRECISION NOT NULL,total DOUBLE PRECISION NOT NULL,cancelado BOOLEAN NOT NULL,compra_id INTEGER REFERENCES compra);
INSERT INTO rol(id_rol,nombre) VALUES (1,'ADMIN'),(2,'CLIENTE'),(3,'NEGOCIO');
SELECT setval(pg_get_serial_sequence('rol','id_rol'),3);
INSERT INTO moneda(nombre,simbolo) VALUES ('Sol','S/'),('Dolar','$');
INSERT INTO unidad_medida(nombre) VALUES ('unidad'),('kg');
INSERT INTO giro(nombre) VALUES ('Comercio');
COMMIT;
